import {courses,lessons,terms,projects} from './content.js';
import {countries,countryNotes} from './countries.js';
import {escapeHTML as E,shuffle,populationChange,energyMix,cleanProgress} from './core.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='geo-expedition-v1';let state;try{state=cleanProgress(JSON.parse(localStorage.getItem(KEY))||{});}catch{state=cleanProgress({});}
let quiz=null,flash=null,mapMode='explore',mapRegion='world',mapTarget=null,mapSelected='EST',mapAnswered=false,world=null,labType='climate',searchCourse=0;
let saveTimer;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(saveTimer);saveTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Браузер не сохранил прогресс. Экспортируй его в разделе «Прогресс».');}}
function activity(xp=0){state.xp+=xp;const d=new Date().toLocaleDateString('sv-SE');if(!state.days.includes(d))state.days.push(d);save();}
function pct(list){return Math.round(list.filter(l=>state.done.includes(l.id)).length/list.length*100)||0;}
function heading(kicker,title,desc){return `<div class="page-intro"><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>`;}
const nav=[['home','⌂','Обзор','Главная'],['courses','▤','Мои курсы','Курсы'],['atlas','◎','Интерактивный атлас','Атлас'],['practice','✧','Тренажёры','Практика'],['labs','⚗','Лаборатория','Лаборатория'],['glossary','Aa','Словарь','Словарь'],['projects','◇','Исследования','Проекты'],['progress','↗','Мой прогресс','Прогресс']];
function navRender(route){$('#nav').innerHTML=nav.map(([id,icon,label,short])=>`<a class="nav-item ${(route===id||id==='courses'&&['course','lesson'].includes(route))?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''} title="${label}"><span class="nav-icon">${icon}</span><span>${label}</span><span class="mobile-label">${short}</span></a>`).join('');$('#breadcrumb').textContent=nav.find(n=>n[0]===route)?.[2]||(['course','lesson'].includes(route)?'Мои курсы / Изучение':'GEO / Экспедиция');}
function globe(){return `<svg viewBox="0 0 430 380" aria-hidden="true"><defs><radialGradient id="ocean"><stop stop-color="#6d9780"/><stop offset="1" stop-color="#355f50"/></radialGradient><clipPath id="sphere"><circle cx="226" cy="186" r="132"/></clipPath></defs><g transform="rotate(-18 226 186)"><ellipse cx="226" cy="186" rx="194" ry="69" fill="none" stroke="#8fad7555"/><ellipse cx="226" cy="186" rx="161" ry="164" fill="none" stroke="#7f9e6530" stroke-dasharray="3 6"/><circle cx="226" cy="186" r="133" fill="url(#ocean)" stroke="#aac39377"/><g clip-path="url(#sphere)" fill="#c7d698"><path d="M104 89l49-26 46 11 7 25-25 13-4 21 16 13-23 28-12 20-28-8-16-30-28-9zM175 194l26 1 24 26 7 33-25 56-17 19-7-45-12-25 10-26zM235 73l39 2 32 22 50 7 8 21-30 12 11 20-32 4-14 23-28-9-13-35-19 9-18-13 8-16-18-10zM244 164l34 13 19 39-22 45-19 13-18-40-18-24 3-31zM317 256l33-12 35 18-15 24-31 2-25-17z"/><path d="M223 128l-11 13 8 10 10-7-1-13zM300 225l6 28-5 12-5-13z"/></g><g fill="none" stroke="#d8e8c021" clip-path="url(#sphere)"><ellipse cx="226" cy="186" rx="62" ry="132"/><ellipse cx="226" cy="186" rx="109" ry="132"/><path d="M94 186h264M108 127h236M107 246h238M226 54v264"/></g><ellipse cx="226" cy="186" rx="194" ry="69" fill="none" stroke="#d0e28b88" stroke-dasharray="310 600"/></g><circle cx="249" cy="126" r="17" fill="#d9ef8240"/><circle cx="249" cy="126" r="6" fill="#e8f4b1" stroke="#fff"/><path d="M254 120l42-34h57" fill="none" stroke="#c8d8aa"/><text x="306" y="79" fill="#e6efd7" font-size="10" font-family="sans-serif" letter-spacing="1">59°N · 25°E</text><circle cx="61" cy="233" r="5" fill="#e4edbf"/><path d="M73 45v12m-6-6h12M363 297v12m-6-6h12" stroke="#b9cd92"/></svg>`;}
function cover(c){if(c.id===1)return `<svg viewBox="0 0 270 145" aria-hidden="true"><circle cx="200" cy="40" r="22" fill="#edf1d9"/><path d="M0 145L93 22l67 90 47-68 63 101" fill="#839e73"/><path d="M29 145l84-106 69 106" fill="#aec196"/><path d="M75 62l18-40 27 42-25-11z" fill="#f3f4e2"/><path d="M102 145l54-89 64 89" fill="#577658"/><path d="M144 78l12-22 17 25-16-7z" fill="#e4ecd6"/><path d="M0 130q72-24 140 5t130-8v18H0" fill="#446b4f"/></svg>`;if(c.id===2)return `<svg viewBox="0 0 270 145" aria-hidden="true"><circle cx="202" cy="34" r="22" fill="#f0f4ef"/><path d="M10 145V76h30v69M48 145V51h36v94M92 145V27h36v118M139 145V68h33v77M183 145V45h42v100M238 145V91h32v54" fill="#83a1a6"/><path d="M15 145V100h34v45M60 145V84h50v61M125 145V59h39v86M179 145V102h48v43" fill="#4f777c"/><g fill="#d9e5d3"><path d="M100 40h7v9h-7zm12 0h7v9h-7zm-12 17h7v9h-7zm12 0h7v9h-7zM136 71h7v9h-7zm12 0h7v9h-7zm-12 17h7v9h-7zm12 0h7v9h-7z"/></g><path d="M0 144h270" stroke="#345958" stroke-width="8"/></svg>`;return `<svg viewBox="0 0 270 145" aria-hidden="true"><circle cx="204" cy="39" r="25" fill="#e6c078"/><path d="M0 122q81-53 142-9t128 4v28H0" fill="#a2ad7b"/><path d="M0 139q89-36 151-4t119-9v19H0" fill="#667d52"/><g stroke="#faf4da" stroke-width="4"><path d="M98 140V61M98 61L68 42M98 61l25-25M98 61l7 37M171 143V89M171 89l-24-16M171 89l22-22M171 89l6 29"/></g><g fill="#496b4b"><path d="M22 128l14-32 14 32zM44 132l16-40 16 40zM233 133l14-30 14 30z"/></g></svg>`;}
function courseCard(c){const ls=lessons.filter(l=>l.course===c.id),p=pct(ls);return `<a class="course-card" href="#course/${c.id}"><div class="course-cover ${c.color}"><span class="course-no">КУРС 0${c.id}</span>${cover(c)}</div><div class="course-content"><div class="eyebrow">${c.tag}</div><h3>${c.title}</h3><p>${c.description}</p><div class="course-meta"><span>▤ ${ls.length} уроков</span><span>◷ ${c.hours} часов программы</span></div><div class="progress-track"><span style="width:${p}%"></span></div><div class="course-foot"><span>${p?'Изучено':'Всё начинается с любопытства'}</span><span>${p}% →</span></div></div></a>`;}
function home(){const next=lessons.find(l=>!state.done.includes(l.id))||lessons[0];return `<div class="welcome"><div><h1>Мир ждёт твоих открытий <span style="color:#a2b483">✳</span></h1><p>Исследуй, задавай вопросы и находи связи.</p></div><span class="pill"><i class="dot"></i> Твой темп. Твой маршрут.</span></div><section class="hero"><div class="hero-copy"><div class="eyebrow">ГЕОГРАФИЯ · ГИМНАЗИЯ · ЭСТОНИЯ</div><h2>Мир становится<br><em>понятнее.</em></h2><p>От недр Земли до городов будущего.<br>Не просто учи географию — исследуй её.</p><a href="#lesson/${next.id}" class="btn lime">${state.done.length?'Продолжить исследование':'Начать путешествие'} <span>↗</span></a></div><div class="hero-art">${globe()}</div><div class="hero-tag">ОДНА ПЛАНЕТА. ТЫСЯЧИ СВЯЗЕЙ.</div></section><div class="stat-row"><div class="stat"><i class="stat-icon">▤</i><div><b>3</b><span>курса по программе</span></div></div><div class="stat"><i class="stat-icon">◎</i><div><b>${lessons.length}</b><span>урока с практикой</span></div></div><div class="stat"><i class="stat-icon">⚗</i><div><b>5</b><span>интерактивных лабораторий</span></div></div><div class="stat"><i class="stat-icon">✧</i><div><b>${state.xp}</b><span>очков за открытия</span></div></div></div><div class="section-head"><h2>Три курса. Целая планета.</h2><a href="#courses">Вся программа ↗</a></div><section class="course-grid">${courses.map(courseCard).join('')}</section><div class="section-head"><h2>Выйди за рамки учебника</h2><a href="#practice">Все тренажёры ↗</a></div><div class="split"><a href="#atlas" class="card atlas-promo"><span class="big-orbit" aria-hidden="true">◎</span><div class="mini-label">ИНТЕРАКТИВНЫЙ АТЛАС</div><h3>А где это на карте?</h3><p>Открой страны, изучи столицы и проверь своё пространственное мышление.</p><span class="btn small secondary">Исследовать карту ↗</span></a><div class="card challenge-card"><div class="mini-label">ВОПРОС ДЛЯ РАЗМЫШЛЕНИЯ</div><h3>Почему Балтийское море<br>менее солёное, чем океан?</h3><p>Подсказка: посмотри на реки, осадки и водообмен.</p><a href="#lesson/12" class="btn small secondary">Найти объяснение →</a></div></div><div class="section-head"><h2>Твои инструменты исследователя</h2></div><div class="course-grid"><a class="card" href="#labs"><div class="mini-label">ЭКСПЕРИМЕНТЫ</div><h3>А что, если…</h3><p class="caption">Измени энергобаланс, демографические потоки или водопользование. Наблюдай последствия.</p></a><a class="card" href="#glossary"><div class="mini-label">RU / ET</div><h3>Говори на языке науки</h3><p class="caption">${terms.length} терминов на русском и эстонском с понятными определениями.</p></a><a class="card" href="#projects"><div class="mini-label">9 ИССЛЕДОВАНИЙ</div><h3>От вопроса к выводу</h3><p class="caption">Настоящие географические задачи, рабочая тетрадь и критерии самопроверки.</p></a></div>`;}
function lessonRow(l){return `<a class="lesson-row" href="#lesson/${l.id}"><span class="num ${state.done.includes(l.id)?'done':''}">${state.done.includes(l.id)?'✓':String(l.id).padStart(2,'0')}</span><div><strong>${l.title}</strong><small>${l.et}</small></div><span class="time">${l.minutes} мин →</span></a>`;}
function coursePage(id){const c=courses.find(c=>c.id===+id);if(!c)return missing();return `${heading('КУРС 0'+c.id+' / '+c.et,c.title,c.description)}<div class="pill">${lessons.filter(l=>l.course===c.id).length} учебных тем · ${c.hours} часов в исходной программе · изучено ${pct(lessons.filter(l=>l.course===c.id))}%</div>${c.modules.map((m,i)=>`<h2 class="module-head">${String(i+1).padStart(2,'0')} / ${m}</h2>${lessons.filter(l=>l.course===c.id&&l.module===i).map(lessonRow).join('')}`).join('')}<div class="action-row"><button class="btn" data-action="start-quiz" data-course="${c.id}">Проверить знания курса →</button><a class="btn secondary" href="#projects">Исследовательская работа</a></div>`;}
function lessonPage(id){const l=lessons.find(l=>l.id===+id);if(!l)return missing();return `${heading(`КУРС ${l.course} / ${courses[l.course-1].modules[l.module]}`,l.title,l.et+' · '+l.minutes+' минут на чтение и практику')}<div class="reading-grid"><article class="card lesson-article"><div class="mini-label">РАЗБЕРИСЬ В ГЛАВНОМ</div>${l.paragraphs.map(p=>`<p>${p}</p>`).join('')}<div class="note"><strong>Посмотри на реальный мир</strong>${l.example}</div><h2>Проверь понимание</h2><div id="lesson-check"><p>${l.question.prompt}</p>${shuffle(l.question.options.map((s,i)=>({s,i}))).map(o=>`<button class="answer" data-action="lesson-answer" data-id="${l.id}" data-value="${o.i}">${o.s}</button>`).join('')}<div id="lesson-feedback" aria-live="polite"></div></div><details><summary>Объясни своими словами</summary><p>Покажи причинно-следственную связь из этого урока. Приведи свой пример и назови условие, при котором вывод может измениться. Сверь объяснение с текстом — автоматическая оценка свободного ответа здесь не используется.</p></details><label for="lesson-note">Мои заметки и вопросы</label><textarea id="lesson-note" data-note="l${l.id}" placeholder="Что стало понятнее? Что ещё стоит проверить?">${E(state.notes['l'+l.id]||'')}</textarea><small class="subtle">Заметки сохраняются в этом браузере.</small><div class="action-row"><button class="btn" data-action="complete" data-id="${l.id}" ${state.done.includes(l.id)?'disabled':''}>${state.done.includes(l.id)?'✓ Урок пройден':'Отметить урок изученным +20'}</button><a class="btn secondary" href="#${l.id<lessons.length?'lesson/'+(l.id+1):'progress'}">${l.id<lessons.length?'Следующий урок →':'Мой прогресс →'}</a></div></article><aside><div class="card sticky"><div class="mini-label">ЯЗЫК ГЕОГРАФИИ</div>${l.terms.map(t=>`<div class="term-chip"><strong>${t.ru}</strong><small>${t.et}</small><p>${t.definition}</p></div>`).join('')}<div class="action-row"><a href="#course/${l.course}" class="btn small secondary">← К программе курса</a><a href="#glossary" class="btn small secondary">Весь словарь</a></div><p class="caption">Самооценка прохождения и результаты тестов хранятся отдельно: чтение ещё не доказывает владение темой.</p></div></aside></div>`;}
function practicePage(){return `${heading('УЧИСЬ ЧЕРЕЗ ДЕЙСТВИЕ','Практика без скуки','Ошибки здесь — подсказки, что стоит разобрать. После каждого ответа ты увидишь объяснение.')}<div class="course-grid">${courses.map(c=>`<div class="card"><div class="mini-label">КУРС ${c.id}</div><h3>${c.title}</h3><p class="caption">10 случайных вопросов по содержанию и понятиям курса. Без ограничения времени.</p><button class="btn" data-action="start-quiz" data-course="${c.id}">Начать тест →</button></div>`).join('')}</div><div class="section-head"><h2>Выбери формат</h2></div><div class="course-grid"><div class="card"><div class="mini-label">ВСЕ ТРИ КУРСА</div><h3>Большая экспедиция</h3><p class="caption">20 вопросов в одном тесте. Итог с разбором и ссылками на уроки.</p><button class="btn secondary" data-action="start-quiz" data-course="0">Смешанный тест</button></div><div class="card"><div class="mini-label">ИНТЕРВАЛЬНОЕ ПОВТОРЕНИЕ</div><h3>Карточки понятий</h3><p class="caption">Вспомни определение перед переворотом карточки. Сложные понятия вернутся в этой сессии.</p><button class="btn secondary" data-action="flash-start">Учить карточки</button></div><div class="card"><div class="mini-label">ПОЛИТИЧЕСКАЯ КАРТА</div><h3>Страны и столицы</h3><p class="caption">Европа и страны из программы. У спорных и особых случаев есть пояснения в атласе.</p><button class="btn secondary" data-action="capital-quiz">Тренировать столицы</button></div><div class="card"><div class="mini-label">ТВОЯ ЗОНА РОСТА</div><h3>Разбор ошибок</h3><p class="caption">${state.mistakes.length} тем для повторения. Вернись к объяснениям и проверь себя заново.</p><button class="btn secondary" data-action="mistake-quiz" ${state.mistakes.length?'':'disabled'}>Повторить сложное</button></div><a class="card" href="#atlas"><div class="mini-label">ПРОСТРАНСТВЕННОЕ МЫШЛЕНИЕ</div><h3>Найди страну</h3><p class="caption">Тренировка на карте с подсветкой правильного местоположения и повторными попытками.</p><span class="btn secondary">Открыть атлас →</span></a><a class="card" href="#labs"><div class="mini-label">ПРИЧИНЫ И СЛЕДСТВИЯ</div><h3>Измени условия</h3><p class="caption">Пять моделей для самостоятельных экспериментов.</p><span class="btn secondary">В лабораторию →</span></a></div>`;}
function questionBank(course){const ls=lessons.filter(l=>!course||l.course===course);return ls.flatMap(l=>[{...l.question,lesson:l.id},...l.terms.map(t=>({prompt:`Какое понятие соответствует определению: «${t.definition}»?`,options:[t.ru,...shuffle(terms.filter(x=>x.ru!==t.ru)).slice(0,2).map(x=>x.ru)],correct:0,explanation:`${t.ru} (${t.et}) — ${t.definition.toLowerCase()}.`,lesson:l.id}))]);}
function beginQuiz(course,errors=false){const bank=questionBank(course).filter(q=>!errors||state.mistakes.includes(q.lesson));quiz={items:shuffle(bank).slice(0,errors?Math.min(10,bank.length):course?10:20).map(q=>({...q,choices:shuffle(q.options.map((s,i)=>({s,correct:i===q.correct})))})),index:0,results:[],answered:false,title:errors?'Работа над ошибками':course?courses[course-1].title:'Большая экспедиция'};location.hash='quiz';render();}
function quizPage(){if(!quiz)return practicePage();if(quiz.index>=quiz.items.length){const score=quiz.results.filter(r=>r.ok).length;return `${heading('ЭКСПЕДИЦИЯ ЗАВЕРШЕНА','Теперь ты знаешь больше',quiz.title)}<div class="card quiz-container"><div class="result-score">${score}<span style="font-size:25px;color:#8c9785"> / ${quiz.items.length}</span></div><h2>${score===quiz.items.length?'Отличная работа с этой подборкой!':'Есть опора для следующего шага.'}</h2><p>Это тренировочный результат, а не официальная школьная оценка. Разбери объяснения и попробуй применить знания в исследовании.</p>${quiz.results.filter(r=>!r.ok).map(r=>`<div class="note"><strong>${r.q.prompt}</strong>${r.q.explanation}${r.q.lesson?`<p><a href="#lesson/${r.q.lesson}"><u>Вернуться к уроку →</u></a></p>`:''}</div>`).join('')}<div class="action-row"><a href="#practice" class="btn">Другой тренажёр</a><a href="#progress" class="btn secondary">Посмотреть прогресс</a></div></div>`;}
const q=quiz.items[quiz.index];return `<div class="quiz-container">${heading('ТРЕНАЖЁР',quiz.title,'Сначала обдумай ответ. Подсказка появится после выбора.')}<div class="quiz-head"><span>Вопрос ${quiz.index+1} из ${quiz.items.length}</span><span>${quiz.results.filter(r=>r.ok).length} правильных</span></div><div class="progress-track"><span style="width:${quiz.index/quiz.items.length*100}%"></span></div><div class="card" style="margin-top:22px"><h2>${q.prompt}</h2>${q.choices.map((o,i)=>`<button class="answer" data-action="quiz-answer" data-value="${i}">${o.s}</button>`).join('')}<div id="quiz-feedback" aria-live="polite"></div></div></div>`;}
function flashPage(){if(!flash)return practicePage();if(!flash.queue.length)return heading('ПОВТОРЕНИЕ','Карточки разобраны','Ты повторил 12 понятий. Проверь, сможешь ли использовать их в объяснении.')+'<a class="btn" href="#practice">К тренажёрам →</a>';const t=flash.queue[0];return `<div class="quiz-container">${heading('RU / ET','Вспомни. Объясни. Проверь.','Постарайся сформулировать определение до переворота карточки.')}<div class="quiz-head"><span>Осталось ${flash.queue.length} карточек</span><span>Уверенно: ${flash.known}</span></div><button class="card flashcard" data-action="flash-flip"><small class="mini-label">${flash.flipped?'ОПРЕДЕЛЕНИЕ':'ЧТО ЭТО ЗНАЧИТ?'}</small><strong>${flash.flipped?t.definition:t.ru}</strong><span>${t.et}</span><small style="margin-top:30px">${flash.flipped?'Оцени, насколько точно ты вспомнил':'Нажми, чтобы перевернуть ↻'}</small></button>${flash.flipped?`<div class="action-row"><button class="btn secondary" data-action="flash-again">Повторить позже</button><button class="btn" data-action="flash-known">Знаю +5</button></div>`:''}</div>`;}
function glossaryPage(){return `${heading('РУССКИЙ + EESTI','Словарь исследователя',`${terms.length} понятий, которые помогают объяснять мир. Ищи на русском или эстонском.`)}<label class="sr-only" for="term-search">Поиск термина</label><input id="term-search" type="search" placeholder="Например: литосфера, ränne, энергия…"><div id="term-results" class="glossary-grid">${termCards(terms)}</div>`;}
function termCards(ts){return ts.length?ts.map(t=>`<a class="card" href="#lesson/${t.lesson}"><small>КУРС ${t.course}</small><h3>${t.ru}</h3><small>${t.et}</small><p>${t.definition}</p><small>Открыть в контексте урока →</small></a>`).join(''):'<p class="empty">Ничего не найдено. Попробуй более короткое слово.</p>';}
function projectsPage(){return `${heading('ОТ ВОПРОСА К ДОКАЗАТЕЛЬСТВУ','Твоя исследовательская мастерская','Девять работ по практической части программы. Собирай данные, сравнивай объяснения, формулируй обоснованный вывод.')}<div class="project-grid">${projects.map((p,i)=>`<div class="card"><div class="mini-label">КУРС ${p.course} · ИССЛЕДОВАНИЕ ${i+1}</div><h3>${p.title}</h3><p>${p.brief}</p><a class="btn secondary" href="#project/${i}">${state.notes['p'+i]?'Продолжить работу':'Открыть задание'} →</a></div>`).join('')}</div>`;}
function projectPage(id){const p=projects[+id];if(!p)return missing();return `${heading('ПРАКТИЧЕСКАЯ РАБОТА / КУРС '+p.course,p.title,p.brief)}<div class="reading-grid"><div class="card"><h2>Маршрут исследования</h2><ol class="checklist">${p.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="note"><strong>Хороший вывод можно проверить</strong>Укажи источник, дату и единицы данных. Раздели наблюдение и объяснение. Назови ограничение или альтернативную причину.</div><label for="project-note">Рабочая тетрадь</label><textarea id="project-note" style="min-height:330px" data-note="p${id}" placeholder="Вопрос исследования:\nДанные и источники (с датами):\nСравнение:\nОбъяснение:\nВывод и ограничения:">${E(state.notes['p'+id]||'')}</textarea><p class="caption">Сохраняется в браузере. Для переноса используй экспорт. Автоматической проверки эссе нет.</p><div class="action-row"><button class="btn" data-action="download-project" data-id="${id}">Скачать работу .txt</button><a class="btn secondary" href="#projects">Другие исследования</a></div></div><aside class="card" style="height:fit-content"><h3>Критерии самопроверки</h3>${['Вопрос сформулирован конкретно','Данные сопоставимы и имеют источник','Причинная связь объяснена','Есть пример и контраргумент','Вывод отвечает на вопрос'].map((s,i)=>`<p><label><input type="checkbox"> ${s}</label></p>`).join('')}<small class="subtle">Чек-лист для текущего просмотра; текст работы сохраняется отдельно.</small></aside></div>`;}
function progressPage(){const p=pct(lessons);return `${heading('ТВОЯ ЭКСПЕДИЦИЯ','Каждый шаг имеет значение','Прогресс хранится только в этом браузере. Экспортируй резервную копию, чтобы перенести его на другое устройство.')}<div class="two-col"><div class="card" style="text-align:center"><div class="mini-label">ИЗУЧЕННЫЕ УРОКИ</div><div class="progress-circle" style="--percent:${p}%"><span>${p}%</span></div><p>${state.done.length} из ${lessons.length} уроков отмечено изученными</p><small class="subtle">Это отметки о прохождении, не измерение всех навыков.</small></div><div class="card"><div class="metric-grid"><div class="metric"><strong>${state.xp}</strong><span>очков</span></div><div class="metric"><strong>${state.quizRuns}</strong><span>тестов завершено</span></div><div class="metric"><strong>${state.days.length}</strong><span>дней занятий</span></div></div><p>Ответов верно: <strong>${state.correct} / ${state.answers}</strong> ${state.answers?'('+Math.round(state.correct/state.answers*100)+'%)':''}</p><p>Найдено стран: <strong>${state.mapCorrect}</strong> · Повторено карточек: <strong>${state.cards}</strong></p><p>Лабораторий опробовано: <strong>${state.labs.length} / 5</strong></p></div></div><div class="section-head"><h2>Открытия в коллекции</h2></div><div class="badge-grid">${[['✧','Первый шаг',state.done.length>=1,'Изучи один урок'],['◎','Картограф',state.mapCorrect>=10,'Найди 10 стран'],['⚗','Экспериментатор',state.labs.length===5,'Опробуй 5 лабораторий'],['▤','Исследователь',state.done.length===lessons.length,'Изучи все уроки']].map(([i,t,ok,d])=>`<div class="badge ${ok?'earned':''}"><b>${i}</b><strong>${t}</strong><small>${ok?'✓ Открыто':d}</small></div>`).join('')}</div><div class="section-head"><h2>Прогресс по курсам</h2></div><div class="course-grid">${courses.map(courseCard).join('')}</div><div class="card" style="margin-top:25px"><h3>Твои данные под твоим контролем</h3><div class="action-row"><button class="btn" data-action="export">Экспортировать прогресс</button><label class="btn secondary" for="import-file">Импортировать копию</label><input type="file" id="import-file" accept="application/json,.json" hidden><button class="btn secondary danger" data-action="reset">Сбросить прогресс</button></div><div id="reset-confirm"></div><p class="caption">Импорт заменяет текущую историю. Заметки не отправляются на сервер. Удаление данных браузера удалит локальный прогресс.</p></div>`;}
function aboutPage(){return `${heading('ПРОЗРАЧНОСТЬ И ИСТОЧНИКИ','Что лежит в основе GEO','Учебная платформа для самостоятельной работы по трём предоставленным программам гимназии Эстонии.')}<div class="card source-links"><h2>Соответствие исходным файлам</h2><div class="table-wrap"><table><thead><tr><th>Файл</th><th>Курс</th><th>Тематические блоки</th></tr></thead><tbody><tr><td>Программа 1 курс.docx</td><td>Maa kui süsteem</td><td>Введение · литосфера · атмосфера · гидросфера · биосфера</td></tr><tr><td>Программа 2 курс.docx</td><td>Rahvastik ja majandus</td><td>Исследования · развитие · население · расселение · экономика</td></tr><tr><td>Программа 3 курс.docx</td><td>Loodusvarad ja nende kasutamine</td><td>Сельское хозяйство · вода · лес · энергетика</td></tr></tbody></table></div><div class="note"><strong>Как читать объём программы</strong>Каждый файл заявляет 35 часов. В третьем тематические часы суммируются до 31: 9 + 8 + 5 + 9. Четыре оставшихся часа можно отвести на повторение и исследование — это предложение платформы, не изменение исходного документа. 42 урока GEO — учебные темы, а не 42 школьных занятия.</div><p>Тексты и задания написаны для этой платформы. Они покрывают тематические блоки, но не заменяют полный учебник, работу с первичными данными и оценивание учителем. Открытые исследования проверяются по критериям самостоятельно. Нумерация курсов сохранена по именам файлов, даже если в библиографии учебник называется иначе.</p><h2>Проверяемые научные источники</h2><ul><li><a href="https://www.usgs.gov/faqs/are-tectonic-plates-floating-magma" target="_blank" rel="noopener">USGS: тектонические плиты и состояние мантии</a></li><li><a href="https://www.ipcc.ch/report/ar6/syr/summary-for-policymakers/" target="_blank" rel="noopener">IPCC AR6: причины современного изменения климата</a></li><li><a href="https://helcom.fi/baltic-sea-trends/eutrophication/" target="_blank" rel="noopener">HELCOM: эвтрофикация Балтийского моря</a></li><li><a href="https://andmed.stat.ee/en/stat" target="_blank" rel="noopener">Statistics Estonia: данные для исследований</a></li><li><a href="https://hdr.undp.org/" target="_blank" rel="noopener">UNDP: показатели человеческого развития</a></li><li><a href="https://geoportaal.maaamet.ee/" target="_blank" rel="noopener">Геопортал Эстонии: карты и пространственные данные</a></li></ul><h2>Модели и карта</h2><p>Все числовые сценарии лабораторий — учебные, не текущая статистика и не прогноз. Упрощения описаны рядом с моделью. Картографическая основа: <a href="https://github.com/johan/world.geo.json" target="_blank" rel="noopener">world.geo.json</a>, исходные данные Natural Earth. Карта обобщена и не предназначена для правового определения границ. Малые страны обозначаются точками; политические особенности поясняются в карточках.</p><p>Содержание подготовлено в октябре 2026 года по предоставленным файлам. Для современных показателей и меняющихся административных статусов всегда проверяй дату первоисточника.</p><h2>Как устроено сохранение</h2><p>Вход не требуется. Прогресс, результаты и заметки находятся в локальном хранилище браузера. Между устройствами они автоматически не синхронизируются; доступен экспорт и импорт. Шрифты могут загружаться с Google Fonts; учебные материалы и карта размещены вместе с сайтом.</p></div>`;}
function searchPage(){return `${heading('ПОИСК','Найди свою следующую тему','Поиск по названиям, текстам уроков и русско-эстонским понятиям.')}<label for="global-search" class="sr-only">Поиск по платформе</label><input id="global-search" type="search" placeholder="Например: вода, население, Балтийское море…" autofocus><div id="search-results"><p class="subtle">Начни вводить запрос.</p></div>`;}
function missing(){return heading('GEO','Такой страницы нет','Выбери курс или вернись к обзору.')+'<a class="btn" href="#home">На главную</a>';}
function atlasPage(){return `${heading('СМОТРИ НА МИР ШИРЕ','Интерактивный атлас','Исследуй страны из программы. Увеличь Европу, открой карточку страны или переключись в тренировку.')}<div class="tabs"><button class="tab ${mapMode==='explore'?'active':''}" data-action="map-mode" data-value="explore">Исследовать</button><button class="tab ${mapMode==='quiz'?'active':''}" data-action="map-mode" data-value="quiz">Найди страну</button><button class="tab ${mapRegion==='world'?'active':''}" data-action="map-region" data-value="world">Весь мир</button><button class="tab ${mapRegion==='europe'?'active':''}" data-action="map-region" data-value="europe">Европа крупнее</button></div>${mapMode==='quiz'?`<div class="map-task"><p>Найди на карте: <strong>${mapTarget?.name||'Эстония'}</strong><br><small id="map-feedback" aria-live="polite">Нажми на территорию или точку страны. Названия скрыты до ответа.</small></p><button class="btn small secondary" data-action="map-next">${mapAnswered?'Следующая →':'Пропустить →'}</button></div>`:''}<div class="map-layout"><div><div class="map-shell"><svg id="world-map" viewBox="${mapRegion==='world'?'0 0 720 360':'306 32 155 91'}" aria-label="Политическая карта мира. Страны можно выбирать клавишей Enter." role="group"></svg><div class="map-controls"><button class="btn small secondary" data-action="map-region" data-value="europe">＋ Европа</button><button class="btn small secondary" data-action="map-region" data-value="world">− Весь мир</button></div></div><p class="caption">Упрощённая равнопромежуточная проекция: площади и формы искажаются. Точки обозначают учебные позиции, не столицы. Основа: Natural Earth / world.geo.json.</p></div><aside class="card map-info" id="map-info">${mapMode==='explore'?countryInfo(mapSelected):'<h3>Исследуй форму и соседей</h3><p class="caption">В режиме тренировки список скрыт. Для маленьких стран удобнее увеличить Европу.</p><p class="caption">Задания по Европе включают микрогосударства, обозначенные точками.</p>'}</aside></div>`;}
function countryInfo(id){const c=countries.find(x=>x.id===id);if(!c)return '<h3>Выбери страну</h3>';return `<div class="mini-label">${c.region}</div><h2>${c.name}</h2><div class="term-chip"><small>СТОЛИЦА</small><strong>${c.capital}</strong></div>${countryNotes[id]?`<p class="caption">${countryNotes[id]}</p>`:''}<label for="country-search">Быстрый поиск страны</label><input id="country-search" type="search" placeholder="Название…"><div class="country-list" id="country-results">${countryButtons(countries)}</div>`;}
function countryButtons(cs){return cs.map(c=>`<button class="country-button" data-action="country-select" data-id="${c.id}">${c.name}</button>`).join('');}
const projectPoint=([x,y])=>[(x+180)*2,(90-y)*2];
function pathGeo(geometry){const ps=geometry.type==='Polygon'?[geometry.coordinates]:geometry.type==='MultiPolygon'?geometry.coordinates:[];return ps.flatMap(p=>p.map(r=>r.map((xy,i)=>{const [x,y]=projectPoint(xy);return `${i?'L':'M'}${x.toFixed(2)},${y.toFixed(2)}`;}).join('')+'Z')).join('');}
async function drawMap(){const svg=$('#world-map');if(!svg)return;try{if(!world){const r=await fetch('./world.json');if(!r.ok)throw Error();world=await r.json();}if(!svg.isConnected)return;const explore=mapMode==='explore';svg.innerHTML=`<rect x="0" y="0" width="720" height="360" fill="#e7efeb"/>${Array.from({length:11},(_,i)=>`<path d="M${i*72} 0v360" stroke="#d4e1db" stroke-width=".5"/>`).join('')}${Array.from({length:5},(_,i)=>`<path d="M0 ${(i+1)*60}h720" stroke="#d4e1db" stroke-width=".5"/>`).join('')}${world.features.map(f=>{const c=countries.find(c=>c.id===f.id);return `<path d="${pathGeo(f.geometry)}" fill-rule="evenodd" class="land ${explore&&mapSelected===f.id?'selected':''} ${mapAnswered&&mapTarget?.id===f.id?'target':''}" data-action="map-pick" data-id="${E(f.id)}" ${c?`tabindex="0" role="button" aria-label="${explore?E(c.name):'Территория страны'}"`:''}>${explore?`<title>${E(c?.name||f.properties.name)}</title>`:''}</path>`;}).join('')}${countries.filter(c=>mapRegion==='world'||c.region.includes('Европа')).map(c=>{const [x,y]=projectPoint([c.lon,c.lat]);return `<circle cx="${x}" cy="${y}" r="${mapRegion==='europe'?.65:1.5}" class="map-dot ${mapAnswered&&mapTarget?.id===c.id?'target':''}" data-action="map-pick" data-id="${c.id}" tabindex="0" role="button" aria-label="${explore?c.name:'Точка страны'}">${explore?`<title>${c.name}</title>`:''}</circle>`;}).join('')}`;}catch{svg.outerHTML='<p class="empty">Не удалось загрузить карту. Перезагрузи страницу. Список стран доступен справа.</p>';}}
function nextMap(){const pool=countries.filter(c=>mapRegion==='world'?!['IDN'].includes(c.id):c.region==='Европа');mapTarget=shuffle(pool.filter(c=>c.id!==mapTarget?.id))[0];mapAnswered=false;}
const labNames={climate:'Климатограмма',population:'Демография',energy:'Энергобаланс',water:'Водный баланс',plates:'Тектоника плит'};
function labsPage(){return `${heading('МЕНЯЙ УСЛОВИЯ. НАБЛЮДАЙ СВЯЗИ.','Географическая лаборатория','Пять учебных моделей. Сначала предположи результат, затем измени параметры и объясни, что произошло.')}<div class="tabs">${Object.entries(labNames).map(([id,name])=>`<button class="tab ${labType===id?'active':''}" data-action="lab-tab" data-value="${id}">${name}</button>`).join('')}</div><div id="lab-content">${labHTML()}</div>`;}
function slider(id,label,min,max,value,unit=''){return `<label for="${id}">${label} <output id="${id}-value">${value}${unit}</output></label><input type="range" data-lab-input id="${id}" min="${min}" max="${max}" value="${value}" data-unit="${unit}">`;}
function labHTML(){if(labType==='climate')return `<div class="lab-layout"><div class="card"><div class="mini-label">КЛИМАТ В ЧИСЛАХ</div><label for="climate-type">Учебный тип климата</label><select id="climate-type" data-lab-input><option value="maritime">Умеренный морской</option><option value="continental">Умеренный континентальный</option><option value="tropical">Влажный экваториальный</option><option value="desert">Тропический пустынный</option><option value="mediterranean">Средиземноморский</option></select>${slider('warming','Сдвиг температуры',-5,5,0,' °C')}<p class="caption">Синтетические месячные данные для сравнения, не наблюдения в конкретном городе. Сдвиг температуры не моделирует изменение осадков.</p><button class="btn small" data-action="lab-done">Сохранить эксперимент +15</button></div><div class="card"><h3>Температура и осадки по месяцам</h3><div id="lab-output"></div><details><summary>Как читать климатограмму?</summary><p>Оранжевая линия — температура (левая шкала, °C), столбцы — осадки (правая шкала, мм). Найди сезон максимумов, амплитуду температуры и годовую сумму осадков. Высота столбца и температура не сравниваются напрямую.</p></details></div></div>`;
if(labType==='population')return `<div class="lab-layout"><div class="card"><div class="mini-label">ОДИН УСЛОВНЫЙ ГОД</div>${slider('births','Родилось',0,3000,900)}${slider('deaths','Умерло',0,3000,1100)}${slider('incoming','Прибыло',0,3000,800)}${slider('outgoing','Выбыло',0,3000,300)}<button class="btn small" data-action="lab-done">Сохранить эксперимент +15</button></div><div class="card"><h3>Население: что меняет итог?</h3><p class="caption">Условный город: 100 000 жителей в начале года. Все потоки заданы в людях, не в промилле.</p><div id="lab-output"></div><div class="note"><strong>Задача</strong>Сохрани отрицательный естественный прирост, но добейся роста общего населения. Какая причина объясняет результат?</div></div></div>`;
if(labType==='energy')return `<div class="lab-layout"><div class="card"><div class="mini-label">СОБЕРИ СВОЙ ЭНЕРГОБАЛАНС</div>${slider('fossil','Ископаемое топливо',0,100,40)}${slider('wind','Ветер',0,100,25)}${slider('solar','Солнце',0,100,15)}${slider('nuclear','Атомная энергия',0,100,20)}<p class="caption">Вес каждого источника нормируется к сумме 100%. Это доли выработки, не установленной мощности.</p><button class="btn small" data-action="lab-done">Сохранить эксперимент +15</button></div><div class="card"><h3>Выбросы и переменная выработка</h3><div id="lab-output"></div><p class="caption">Учебные коэффициенты жизненного цикла: 700 / 12 / 45 / 12 г CO₂-экв./кВт·ч соответственно. Это условные округлённые значения для модели, не показатели конкретных станций. Модель не оценивает стоимость, почасовую надёжность и потребность в накопителях.</p><div class="note"><strong>Объясни компромисс</strong>Снизь среднюю углеродоёмкость. Какие дополнительные данные понадобятся, чтобы убедиться в надёжности этой системы зимой?</div></div></div>`;
if(labType==='water')return `<div class="lab-layout"><div class="card"><div class="mini-label">ВОДОСБОР ЗА ГОД</div>${slider('rain','Осадки',0,1500,700,' мм')}${slider('evap','Испарение',0,1000,450,' мм')}${slider('use','Безвозвратное изъятие',0,500,100,' мм')}<button class="btn small" data-action="lab-done">Сохранить эксперимент +15</button></div><div class="card"><h3>Хватит ли поступающей воды?</h3><div id="lab-output"></div><p class="caption">Упрощённый бассейн: нет внешнего притока. Остаток P − E − W при неотрицательном значении может обеспечить сток при неизменном запасе. Отрицательный остаток означает расход запаса или невозможность поддерживать заданные потоки. Испарение и изъятие считаются раздельно, без двойного счёта.</p><div class="note"><strong>Проверь устойчивость</strong>Что произойдёт с запасом, если такой дефицит повторяется пять лет? Почему наличие большого запаса ещё не доказывает устойчивость водопользования?</div></div></div>`;
return `<div class="lab-layout"><div class="card"><div class="mini-label">ТРИ ТИПА ГРАНИЦ</div><label for="plate-type">Взаимодействие плит</label><select id="plate-type" data-lab-input><option value="divergent">Расхождение</option><option value="convergent">Субдукция</option><option value="transform">Боковое смещение</option></select>${slider('plate-step','Продвижение модели',0,100,30,'%')}<p class="caption">Схема без масштаба. Ползунок показывает ход процесса, а не реальную скорость в сантиметрах за год.</p><button class="btn small" data-action="lab-done">Сохранить эксперимент +15</button></div><div class="card"><h3>Как меняется граница?</h3><div id="lab-output"></div><div class="note"><strong>Перенеси объяснение на карту</strong>Сопоставь модель с Исландией, Андами и разломом Сан-Андреас. Где образуется кора, а где она погружается?</div></div></div>`;}
const val=id=>Number($('#'+id)?.value||0);
function labUpdate(){const out=$('#lab-output');if(!out)return;$$('[data-lab-input][type=range]').forEach(el=>{const o=$('#'+el.id+'-value');if(o)o.textContent=el.value+(el.dataset.unit||'');});if(labType==='climate'){const data={maritime:[[-2,-2,1,6,12,16,18,17,12,7,3,0],[45,35,38,35,45,65,75,80,65,70,60,50]],continental:[[-18,-15,-6,5,14,20,23,20,12,3,-8,-15],[18,15,20,30,45,60,70,55,38,30,25,20]],tropical:[[26,26,27,27,27,26,26,26,26,26,26,26],[220,200,250,260,230,180,160,170,190,230,250,240]],desert:[[15,17,21,26,31,35,37,36,32,26,20,16],[5,4,4,2,1,0,0,0,0,1,3,5]],mediterranean:[[10,11,13,16,20,24,27,27,24,20,15,11],[80,65,50,40,25,10,3,5,25,60,85,95]]}[$('#climate-type').value];const ts=data[0].map(v=>v+val('warming')),rs=data[1],months=['Я','Ф','М','А','М','И','И','А','С','О','Н','Д'];out.innerHTML=`<svg class="lab-chart" viewBox="0 0 620 310" role="img" aria-label="Учебная климатограмма"><text x="20" y="20" fill="#b37a49" font-size="12">°C</text><text x="578" y="20" fill="#6d9ca9" font-size="12">мм</text>${[-20,0,20,40].map(t=>{const y=270-(t+20)*3.5;return `<path d="M45 ${y}H575" stroke="#e1e7db"/><text x="12" y="${y+4}" font-size="11" fill="#778578">${t}</text>`;}).join('')}${[0,100,200,300].map(v=>`<text x="580" y="${274-v*.7}" font-size="11" fill="#778578">${v}</text>`).join('')}${rs.map((v,i)=>`<rect x="${57+i*43}" y="${270-v*.7}" width="24" height="${v*.7}" rx="3" fill="#a1bec4"/><text x="${64+i*43}" y="293" font-size="11" fill="#778578">${months[i]}</text>`).join('')}<polyline class="graph-line" points="${ts.map((t,i)=>`${69+i*43},${270-(t+20)*3.5}`).join(' ')}"/>${ts.map((t,i)=>`<circle cx="${69+i*43}" cy="${270-(t+20)*3.5}" r="3" fill="#d0915d"/>`).join('')}</svg><div class="metric-grid"><div class="metric"><strong>${(ts.reduce((a,b)=>a+b)/12).toFixed(1)}°</strong><span>средняя за год</span></div><div class="metric"><strong>${Math.max(...ts)-Math.min(...ts)}°</strong><span>годовая амплитуда</span></div><div class="metric"><strong>${rs.reduce((a,b)=>a+b)}</strong><span>осадки, мм/год</span></div></div><details><summary>Таблица данных</summary><div class="table-wrap"><table><tr><th>Месяц</th>${months.map(m=>`<th>${m}</th>`).join('')}</tr><tr><td>°C</td>${ts.map(t=>`<td>${t}</td>`).join('')}</tr><tr><td>мм</td>${rs.map(r=>`<td>${r}</td>`).join('')}</tr></table></div></details>`;}
if(labType==='population'){const d=populationChange(val('births'),val('deaths'),val('incoming'),val('outgoing'));out.innerHTML=`<div class="metric-grid">${[['Естественный прирост',d.natural],['Миграционное сальдо',d.migration],['Общее изменение',d.total]].map(([s,v])=>`<div class="metric"><strong>${v>0?'+':''}${v}</strong><span>${s}</span></div>`).join('')}</div><svg class="lab-chart" viewBox="0 0 550 240" role="img" aria-label="Вклад четырёх потоков в изменение населения">${[['Рождения',val('births'),'#8fae70'],['Смерти',val('deaths'),'#c99481'],['Прибытие',val('incoming'),'#7fabb1'],['Выбытие',val('outgoing'),'#c9b279']].map(([s,v,c],i)=>`<text x="8" y="${35+i*50}" fill="#687867" font-size="12">${s}</text><rect x="90" y="${17+i*50}" width="${v/9}" height="27" rx="4" fill="${c}"/><text x="${100+v/9}" y="${36+i*50}" font-size="12" fill="#395a46">${v}</text>`).join('')}</svg><h3>В конце года: ${(100000+d.total).toLocaleString('ru-RU')} жителей</h3><p class="caption">Изменение: ${(d.total/1000).toFixed(1)}%. Модель не прогнозирует будущую рождаемость и миграцию.</p>`;}
if(labType==='energy'){const ss=['fossil','wind','solar','nuclear'].map(val),sum=ss.reduce((a,b)=>a+b),names=['Топливо','Ветер','Солнце','Атом'],colors=['#6b8270','#a1bd79','#e6c478','#7da7ac'];out.innerHTML=sum?`<div style="height:45px;display:flex;border-radius:9px;overflow:hidden;margin:30px 0">${ss.map((s,i)=>`<div style="width:${s/sum*100}%;background:${colors[i]}" title="${names[i]}: ${(s/sum*100).toFixed(1)}%"></div>`).join('')}</div><div class="table-wrap"><table>${ss.map((s,i)=>`<tr><td><span style="color:${colors[i]}">●</span> ${names[i]}</td><td>${(s/sum*100).toFixed(1)}%</td></tr>`).join('')}</table></div><div class="metric-grid"><div class="metric"><strong>${Math.round(energyMix(ss,[700,12,45,12]))}</strong><span>г CO₂-экв./кВт·ч</span></div><div class="metric"><strong>${Math.round((ss[1]+ss[2])/sum*100)}%</strong><span>переменная выработка</span></div><div class="metric"><strong>${Math.round(ss[0]/sum*100)}%</strong><span>ископаемая энергия</span></div></div>`:'<div class="note">Добавь хотя бы один источник: при нулевой выработке баланс не определён.</div>';}
if(labType==='water'){const r=val('rain')-val('evap')-val('use');out.innerHTML=`<div class="metric-grid"><div class="metric"><strong>${val('rain')}</strong><span>поступление, мм</span></div><div class="metric"><strong>${val('evap')+val('use')}</strong><span>расход, мм</span></div><div class="metric"><strong>${r}</strong><span>остаток, мм</span></div></div><svg viewBox="0 0 550 210" class="lab-chart" role="img" aria-label="Схема остатка водного баланса"><rect x="70" y="20" width="400" height="170" rx="18" fill="#edf2e5"/><rect x="70" y="${190-Math.min(160,Math.max(0,r)*.2)}" width="400" height="${Math.min(160,Math.max(0,r)*.2)}" rx="18" fill="#94b8bf"/><text x="270" y="100" text-anchor="middle" fill="#315643" font-size="22">${r<0?'Дефицит: расходуется запас':r===0?'Нет остатка для стока':'Вода для стока: '+r+' мм'}</text></svg><p>${r<0?'Потоки нельзя поддерживать бесконечно: сократи изъятие, проверь испарение и восполнение.':'Не весь остаток можно изъять: речным и прибрежным экосистемам тоже нужна вода.'}</p>`;}
if(labType==='plates'){const type=$('#plate-type').value,s=val('plate-step')*.35;const desc={divergent:'Плиты расходятся. Поднимающийся расплав создаёт новую океаническую кору. Пример: Срединно-Атлантический хребет.',convergent:'Океаническая плита погружается под другую. Возможны глубоководный желоб, землетрясения и вулканическая дуга. Пример: запад Южной Америки.',transform:'Плиты смещаются вдоль границы. Кора здесь не создаётся и не уничтожается; накапливающееся напряжение может разрядиться землетрясением. Вид сверху, пример: Сан-Андреас.'}[type];out.innerHTML=`<svg class="lab-chart" viewBox="0 0 550 270" role="img" aria-label="${E(desc)}"><rect x="15" y="130" width="520" height="100" rx="8" fill="#d5ae82"/><text x="275" y="250" font-size="12" text-anchor="middle" fill="#8b795e">${type==='transform'?'Вид сверху · схема без масштаба':'Астеносфера · преимущественно твёрдая, пластичная'}</text>${type==='divergent'?`<path d="M15 100H${267-s}v50H15z" fill="#8ca884"/><path d="M${283+s} 100H535v50H${283+s}z" fill="#65816a"/><path d="M${260-s} 170L275 90l${15+s} 80" fill="#db966d"/><text x="150" y="75" font-size="32" fill="#41634c">←</text><text x="355" y="75" font-size="32" fill="#41634c">→</text>`:type==='convergent'?`<path d="M15 105H270l${100+s} 96-25 15-90-68H15z" fill="#79938a"/><path d="M${280-s/3} 102H535v45H315z" fill="#adc08c"/><path d="M360 105l25-40 30 40" fill="#557657"/><text x="145" y="80" font-size="32" fill="#41634c">→</text><text x="430" y="80" font-size="32" fill="#41634c">←</text>`:`<rect x="20" y="${50-s}" width="250" height="150" fill="#8eac86"/><rect x="280" y="${50+s}" width="250" height="150" fill="#5f826d"/><text x="135" y="125" font-size="35" fill="white">↑</text><text x="395" y="125" font-size="35" fill="white">↓</text>`}</svg><div class="note">${desc}</div>`;}}
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function render(){const [route='home',id]=(location.hash.slice(1)||'home').split('/');navRender(route);const pages={home,courses:()=>heading('УЧЕБНЫЙ МАРШРУТ','Три курса географии','Выбери тему или двигайся последовательно. Уроки, практика и исследования связаны между собой.')+`<div class="course-grid">${courses.map(courseCard).join('')}</div><div class="note">На телефоне словарь, исследования и прогресс также доступны здесь: <a href="#glossary"><u>словарь</u></a> · <a href="#projects"><u>исследования</u></a> · <a href="#progress"><u>прогресс</u></a>.</div>`,course:()=>coursePage(id),lesson:()=>lessonPage(id),practice:practicePage,quiz:quizPage,flash:flashPage,glossary:glossaryPage,projects:projectsPage,project:()=>projectPage(id),progress:progressPage,about:aboutPage,search:searchPage,atlas:atlasPage,labs:labsPage};$('#main').innerHTML=(pages[route]||missing)();if(route==='atlas')drawMap();if(route==='labs')labUpdate();document.title=`${({home:'Мир становится понятнее',lesson:lessons.find(l=>l.id===+id)?.title,course:courses.find(c=>c.id===+id)?.title,quiz:'Тренировка',flash:'Карточки понятий',about:'О программе',project:projects[+id]?.title,search:'Поиск'}[route]||nav.find(n=>n[0]===route)?.[2]||'Исследуй мир')} — GEO`;}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=+el.dataset.id,v=el.dataset.value;
if(a==='complete'){if(!state.done.includes(id)){state.done.push(id);activity(20);toast('Урок отмечен изученным. +20 очков');el.disabled=true;el.textContent='✓ Урок пройден';}}
if(a==='lesson-answer'){const l=lessons.find(l=>l.id===id),ok=+v===0;$$('#lesson-check .answer').forEach(b=>{b.disabled=true;if(+b.dataset.value===0)b.classList.add('correct');});if(!ok)el.classList.add('wrong');$('#lesson-feedback').innerHTML=`<div class="feedback ${ok?'':'bad'}"><strong>${ok?'Верно.':'Разберёмся.'}</strong> ${l.question.explanation}</div>`;state.answers++;if(ok)state.correct++;else if(!state.mistakes.includes(id))state.mistakes.push(id);activity(ok?5:0);}
if(a==='start-quiz')beginQuiz(+el.dataset.course);
if(a==='mistake-quiz')beginQuiz(0,true);
if(a==='capital-quiz'){quiz={title:'Страны и столицы',index:0,results:[],answered:false,items:shuffle(countries.filter(c=>!['IDN','ISR','XKX','ZAF','BOL','CHE'].includes(c.id))).slice(0,12).map(c=>({prompt:`Столица страны «${c.name}»?`,explanation:`${c.name} — ${c.capital}. ${countryNotes[c.id]||''}`,choices:shuffle([{s:c.capital,correct:true},...shuffle(countries.filter(x=>x.capital!==c.capital)).slice(0,3).map(x=>({s:x.capital,correct:false}))])}))};location.hash='quiz';render();}
if(a==='quiz-answer'&&quiz&&!quiz.answered){quiz.answered=true;const q=quiz.items[quiz.index],ok=q.choices[+v].correct;quiz.results.push({q,ok});state.answers++;if(ok){state.correct++;if(q.lesson)state.mistakes=state.mistakes.filter(i=>i!==q.lesson);}else if(q.lesson&&!state.mistakes.includes(q.lesson))state.mistakes.push(q.lesson);activity(ok?10:0);$$('.answer').forEach((b,i)=>{b.disabled=true;if(q.choices[i].correct)b.classList.add('correct');});if(!ok)el.classList.add('wrong');$('#quiz-feedback').innerHTML=`<div class="feedback ${ok?'':'bad'}"><strong>${ok?'Верно! +10 очков.':'Пока не так.'}</strong> ${q.explanation}</div><button class="btn" data-action="quiz-next">${quiz.index===quiz.items.length-1?'Посмотреть результат':'Следующий вопрос'} →</button>`;}
if(a==='quiz-next'&&quiz?.answered){quiz.index++;quiz.answered=false;if(quiz.index===quiz.items.length){state.quizRuns++;activity();}render();}
if(a==='flash-start'){flash={queue:shuffle(terms).slice(0,12),flipped:false,known:0};location.hash='flash';render();}
if(a==='flash-flip'){flash.flipped=!flash.flipped;render();}
if(a==='flash-again'){flash.queue.push(flash.queue.shift());flash.flipped=false;render();}
if(a==='flash-known'){flash.queue.shift();flash.known++;flash.flipped=false;state.cards++;activity(5);render();}
if(a==='map-mode'){mapMode=v;if(v==='quiz')nextMap();render();}
if(a==='map-region'){mapRegion=v;if(mapMode==='quiz')nextMap();render();}
if(a==='map-next'){nextMap();render();}
if(a==='country-select'){mapSelected=el.dataset.id;$('#map-info').innerHTML=countryInfo(mapSelected);drawMap();}
if(a==='map-pick'){const c=countries.find(c=>c.id===el.dataset.id);if(mapMode==='explore'){if(c){mapSelected=c.id;$('#map-info').innerHTML=countryInfo(c.id);drawMap();}else toast('Эта территория пока не включена в учебные карточки.');}else if(!mapAnswered){mapAnswered=true;document.querySelector('[data-action=map-next]').textContent='Следующая →';const ok=el.dataset.id===mapTarget.id;if(ok){state.mapCorrect++;activity(10);}$('#map-feedback').textContent=ok?'Верно! +10 очков. Переходи к следующей стране.':`Это ${c?.name||'другая территория'}. ${mapTarget.name} выделена золотистым цветом. Посмотри на соседей.`;$('#map-info').innerHTML=`<h3>${mapTarget.name}</h3><p>Столица: <strong>${mapTarget.capital}</strong></p><p class="caption">${countryNotes[mapTarget.id]||mapTarget.region}</p>`;drawMap();}}
if(a==='lab-tab'){labType=v;render();}
if(a==='lab-done'){if(!state.labs.includes(labType)){state.labs.push(labType);activity(15);toast('Эксперимент отмечен. +15 очков');}else toast('Эта лаборатория уже отмечена. Продолжай исследовать условия.');}
if(a==='download-project'){download('GEO-'+projects[id].title+'.txt',projects[id].title+'\n\n'+(state.notes['p'+id]||'Заметки ещё не добавлены.'));}
if(a==='export')download('geo-progress.json',JSON.stringify(state,null,2),'application/json');
if(a==='reset')$('#reset-confirm').innerHTML='<div class="note"><strong>Удалить результаты и все заметки из этого браузера?</strong>Сначала экспортируй копию, если хочешь сохранить их.<div class="action-row"><button class="btn danger secondary" data-action="reset-confirm">Да, удалить</button><button class="btn secondary" data-action="reset-cancel">Отмена</button></div></div>';
if(a==='reset-cancel')$('#reset-confirm').innerHTML='';
if(a==='reset-confirm'){state=cleanProgress({});save();render();toast('Локальный прогресс сброшен.');}
});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.note){state.notes[el.dataset.note]=el.value.slice(0,20000);save();}if(el.id==='term-search')$('#term-results').innerHTML=termCards(terms.filter(t=>(t.ru+' '+t.et+' '+t.definition).toLocaleLowerCase().includes(el.value.trim().toLocaleLowerCase())));if(el.id==='country-search')$('#country-results').innerHTML=countryButtons(countries.filter(c=>c.name.toLocaleLowerCase().includes(el.value.toLocaleLowerCase())));if(el.id==='global-search'){const q=el.value.trim().toLocaleLowerCase().replace(/([а-яё]{4,})(ское|ская|ский|ские|ого|ому|ами|ями|ой|ый|ий|ая|ое|ые)$/u,(_,stem)=>stem);$('#search-results').innerHTML=q?lessons.filter(l=>(l.title+' '+l.et+' '+l.example+' '+l.paragraphs.join(' ')+' '+l.terms.map(t=>t.ru+' '+t.et).join(' ')).toLocaleLowerCase().includes(q)).map(lessonRow).join('')||'<p class="empty">Ничего не найдено. Попробуй другой термин.</p>':'<p class="subtle">Начни вводить запрос.</p>';}if(el.hasAttribute('data-lab-input'))labUpdate();});
document.addEventListener('change',async e=>{if(e.target.id==='import-file'){const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error();const parsed=JSON.parse(await f.text());if(parsed.version!==1||!Array.isArray(parsed.done))throw Error();if(!confirm('Заменить текущий прогресс и заметки данными из файла?'))return;state=cleanProgress(parsed);save();render();toast('Прогресс импортирован.');}catch{toast('Не удалось прочитать копию. Нужен JSON-файл экспорта GEO (до 2 МБ).');}}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('svg [data-action]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();location.hash='search';setTimeout(()=>$('#global-search')?.focus(),0);}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
render();
